#!/usr/bin/env python3
import json, pathlib
ROOT = pathlib.Path(__file__).resolve().parents[1]
rows = [
  {"q":"Rincian biaya kuliah ITB AAS berapa?","a":"Website mencantumkan: registrasi/pendaftaran Rp200.000; jas almamater Rp200.000; SPP+praktik per bulan D3 Rp350.000, D4/S1 Rp400.000; skripsi/tugas akhir D3 Rp750.000, D4/S1 Rp1.000.000. Post 2026 juga mengklaim bebas biaya SKS/UTS/UAS. Berlaku untuk tahun akademik berjalan dan bisa berubah—konfirmasi ke PMB/keuangan.","source":"https://itbaas.id/"},
  {"q":"DPA/uang gedung berapa?","a":"Website mencantumkan DPA: Gelombang Dini Des–Jan D4/S1 Rp2.000.000 dan D3 Rp1.200.000; Gelombang 1 Feb–Apr Rp2.500.000/Rp1.500.000; Gelombang 2 Mei–Jun Rp3.000.000/Rp2.000.000; Gelombang 3 Jul–Agu Rp3.500.000/Rp2.500.000. Bisa berubah/diangsur sesuai kesepakatan—cek PMB.","source":"https://itbaas.id/"},
  {"q":"Apakah ada biaya SKS/UTS/UAS?","a":"Beberapa post website mengklaim biaya SKS, UTS, dan UAS sudah termasuk/bebas biaya tambahan. Ini klaim website, bukan hasil audit independen. Tanyakan rincian resmi ke PMB/keuangan sebelum bayar.","source":"https://itbaas.id/kuliah-online-kelas-karyawan-solo-biaya-murah/"},
  {"q":"Pembayaran bisa dicicil?","a":"Website menyebut SPP bulanan dan DPA/uang gedung dapat dibayar bertahap sesuai kesepakatan dengan bagian keuangan. Skema cicilan per prodi/gelombang tidak dijamin di KB—minta rincian tertulis ke PMB/keuangan.","source":"https://itbaas.id/kampus-swasta-solo-terbaik-itb-aas-indonesia/"},
  {"q":"Jalur RPL itu untuk siapa?","a":"Untuk pekerja/profesional/ASN/pelaku usaha dengan pengalaman kerja minimal ±2 tahun atau sertifikat pelatihan; kompetensi/pengalaman dikonversi jadi SKS. Target studi biasanya 1–2 tahun. Proses cek konversi SKS gratis disebut di post—verify di PMB.","source":"https://itbaas.id/kuliah-rpl-solo-itb-aas-indonesia-biaya-murah/"},
  {"q":"RPL tersedia di prodi apa?","a":"Post 2026 menyebut: S1 Informatika (LAM-INFOKOM Unggul, SK 012/SK/LAM-INFOKOM/Ak/S/IV/2026), S1 Manajemen (Baik Sekali, SK 3114/DE/A.5/AR.10/XII/2025), S1 Akuntansi (Baik Sekali, SK 1478/DE/A.5/AR.10/VIII/2024), S1 Ekonomi Syariah (Baik Sekali, SK 1464/DE/A.5/AR.10/VIII/2024), D4 Kebijakan dan Manajemen Pajak (Baik Sekali, SK 1906/DE/A.5/AR.10/XII/2024).","source":"https://itbaas.id/kuliah-rpl-solo-itb-aas-indonesia-biaya-murah/"},
  {"q":"Berapa biaya RPL sampai lulus?","a":"Post website menyebut total sekitar Rp16–20 juta hingga lulus, bisa dicicil/5 kali; ada juga paket all-in Rp16 juta dan paket bulanan mulai Rp350 ribu. Angka ini promo website—minta rincian terbaru ke PMB dan cek PDDIKTI.","source":"https://itbaas.id/jalur-rpl-itb-aas-lebih-murah-fleksibel/"},
  {"q":"Apakah RPL legal/resmi?","a":"Post website mengklaim terdaftar di Kemendikbudristek/PDDIKTI/SIERRA dan diakui nasional. KB belum bisa akses PDDIKTI saat build; verifikasi mandiri di pddikti.kemdikbud.go.id atau minta bukti/SK ke PMB.","source":"https://itbaas.id/ubah-pengalaman-kerja-jadi-gelar-sarjana-itb-aas-indonesia-buka-jalur-rpl-resmi-kemendikbudristek"},
  {"q":"Apakah ada kelas karyawan/pegawai?","a":"Ada: pilihan kelas reguler pagi, kelas malam, dan kelas pegawai/karyawan; pembelajaran blended/hybrid/online dengan tatap muka terjadwal (post menyebut Jumat malam/Sabtu). Ketersediaan kelas per prodi tidak dijamin—cek PMB.","source":"https://itbaas.id/pilihan-kuliah-karyawan-solo-raya-itb-aas-indonesia/"},
  {"q":"Bisa kuliah full online?","a":"Website mempromosikan kuliah online/hybrid untuk kelas karyawan. Legalitas, prodi yang bisa full online, dan jadwal tatap muka wajib dikonfirmasi ke PMB; jangan asumsikan semua prodi full online.","source":"https://itbaas.id/kuliah-online-kelas-karyawan-resmi-pddikti-itb-aas-indonesia-solo/"},
  {"q":"S2 Manajemen biayanya berapa?","a":"Post 2026: reguler Rp400.000 pendaftaran + Rp7.000.000/semester × 3 semester = Rp21.000.000 termasuk tesis. Dual Degree M.M.+MBA Rp86.000.000. Alumni ITB AAS disebut diskon 50% biaya pendidikan per semester (total Rp10.500.000 plus komponen lain)—verify.","source":"https://itbaas.id/s2-manajemen-di-solo/"},
  {"q":"S2 Manajemen belajar apa?","a":"Fokus manajerial, kepemimpinan, strategi, keuangan, inovasi, organisasi digital; konsentrasi disebut: pemasaran, SDM, keuangan, strategik, kewirausahaan, digital business, kepemimpinan organisasi. Masa studi 3 semester termasuk tesis.","source":"https://itbaas.id/s2-manajemen-itb-aas-indonesia-2/"},
  {"q":"Apa itu Dual Degree S2?","a":"Program M.M. (ITB AAS) + MBA (International College Rajamangala University of Technology Krungthep/IC-RMUTK Thailand). Post menyebut 3 semester, Rp86.000.000 termasuk pendaftaran, perkuliahan, dan program internasional sesuai ketentuan kerja sama.","source":"https://itbaas.id/s2-manajemen-dual-degree-internasional/"},
  {"q":"Apakah S1 Manajemen juga bisa gelar ganda?","a":"Post website mengklaim mahasiswa S1 Manajemen bisa meraih gelar B.B.A. dari Thailand sekaligus sarjana ITB AAS dalam satu masa studi. Detail kuota/syarat/beasiswa tidak ada di KB—tanya PMB.","source":"https://itbaas.id/kampus-terbaik-solo-itb-aas-indonesia/"},
  {"q":"Apa itu KKN Internasional?","a":"Post website menyebut program KKN Internasional di Thailand sebagai bagian kerja sama; mahasiswa terlibat proyek pengabdian masyarakat skala internasional. Waktu/biaya/seleksi tidak jelas di KB—konfirmasi ke kampus.","source":"https://itbaas.id/itb-aas-indonesia-perkuat-posisi-sebagai-kampus-swasta-terbaik-di-solo-raya-melalui-kerja-sama-global-dengan-ic-utk-thailand"},
  {"q":"KIP Kuliah dapat apa saja?","a":"Website/post mengklaim kuliah gratis 100% sampai lulus dan bantuan biaya hidup; angka yang beredar: Rp800.000–Rp1.400.000 per bulan (post KIP) dan Rp4,8 juta per semester (post beasiswa). Besaran resmi mengikuti ketentuan pemerintah/klaster; verify di PMB atau KIP Kuliah resmi.","source":"https://itbaas.id/mau-kuliah-gratis-di-solo-cek-jalur-beasiswa-kip-kuliah-itb-aas-indonesia-terbaru/"},
  {"q":"Syarat utama KIP Kuliah?","a":"Post website menyebut: WNI; lulusan SMA/SMK/MA/sederajat tahun berjalan atau maksimal 2 tahun; keterbatasan ekonomi dibuktikan KIP Sekolah/KKS/DTKS/SKTM; lulus seleksi akademik PMB. Dokumen dan kuota berubah—cek pengumuman PMB.","source":"https://itbaas.id/mau-kuliah-gratis-di-solo-cek-jalur-beasiswa-kip-kuliah-itb-aas-indonesia-terbaru/"},
  {"q":"Beasiswa yatim piatu/hafiz Qur’an ada?","a":"Ya, post website menyebut Beasiswa Yatim Piatu 100% gratis dan Beasiswa Hafidz Qur’an/Hafiz Qur’an 100%. Syarat hafalan, kuota, dan verifikasi dokumen berubah—hubungi PMB/beasiswa.","source":"https://itbaas.id/kampus-beasiswa-itb-aas-solo/"},
  {"q":"Beasiswa prestasi/luar Jawa apa?","a":"Post website menyebut potongan biaya untuk prestasi akademik/non-akademik dan kemudahan bagi pendaftar luar Jawa. Besar potongan dan prioritas tidak tercantum jelas; minta rincian ke PMB.","source":"https://itbaas.id/beasiswa-itb-aas-indonesia/"},
  {"q":"Fasilitas kampus apa saja?","a":"Yang disebut di halaman/post: SIAKAD, DIGILIB, E-Journal, laboratorium komputer, perpustakaan digital, Wi-Fi/AC/multimedia (D4), ruang pembelajaran, akses teknologi, kelas multimedia, bimbingan magang/sertifikasi pajak. Ketersediaan per prodi berbeda—cek langsung.","source":"https://itbaas.id/d4-kebijakan-dan-manajemen-pajak/"},
  {"q":"Apa itu SIAKAD, DIGILIB, E-Journal?","a":"SIAKAD = Sistem Informasi Akademik untuk data/informasi akademik mahasiswa; DIGILIB = perpustakaan digital; E-Journal = akses publikasi/jurnal ilmiah ITB AAS. Akses login biasanya untuk mahasiswa; kredensial tidak dibagikan publik.","source":"https://itbaas.id/kampus-unggulan-kawasan-solo-untuk-pilihan-pendidikan-tinggi/"},
  {"q":"Akreditasi SK resminya apa saja?","a":"Post/website menyebut: Informatika Unggul LAM-INFOKOM SK 012/SK/LAM-INFOKOM/Ak/S/IV/2026; Manajemen Baik Sekali SK 3114/DE/A.5/AR.10/XII/2025; Akuntansi Baik Sekali SK 1478/DE/A.5/AR.10/VIII/2024; Ekonomi Syariah Baik Sekali SK 1464/DE/A.5/AR.10/VIII/2024; D4 Pajak Baik Sekali SK 1906/DE/A.5/AR.10/XII/2024.","source":"https://itbaas.id/kuliah-rpl-solo-itb-aas-indonesia-biaya-murah/"},
  {"q":"Akreditasi Hukum dan Kebidanan?","a":"Post website menyebut S1 Hukum Akreditasi Baik dan D3 Kebidanan Akreditasi Baik; halaman Unduh mencantumkan sertifikat S1 Hukum 2024 dan D3 Kebidanan 2023–2027. Status terbaru cek BAN-PT/LAM-PT/LAM-PTKes.","source":"https://itbaas.id/unduh/"},
  {"q":"Apakah ITB AAS legal/PDDIKTI?","a":"Website/post mengklaim mahasiswa/dosen terdaftar di PDDIKTI/SIERRA. KB gagal akses PDDIKTI saat build, jadi verifikasi manual: cari ‘Institut Teknologi Bisnis AAS Indonesia’ di pddikti.kemdikbud.go.id atau minta bukti ke PMB.","source":"https://itbaas.id/kuliah-online-kelas-karyawan-resmi-pddikti-itb-aas-indonesia-solo/"},
  {"q":"Alamat Kampus 1 dan Kampus 2?","a":"Kampus 1: Jl. Slamet Riyadi No. 361 Windan, Makamhaji, Kartasura, Sukoharjo. Kampus 2: Jl. Hamzah Raya, Dusun III, Gumpang, Kec. Kartasura, Kabupaten Sukoharjo (post resmi menyebut Kampus 2/BLKK Yayasan Amaliyah Ilmi Surakarta; juga tertulis Jl. Hamzah Raya Kudusan Gumpang Kartasura).","source":"https://itbaas.id/asesmen-lapangan-program-studi-s1-akuntansi/"},
  {"q":"Kebidanan kuliah di Wonogiri?","a":"Tidak. Kebidanan dilaksanakan di ITB AAS Indonesia; Wonogiri hanya jejak penggabungan Akademi Kebidanan Giri Satria Husada ke ITB AAS pada 2024. Untuk jadwal/lokasi kelas Kebidanan dan Kampus 2, konfirmasi ke PMB/admin karena pemakaian ruang bisa berubah.","source":"https://itbaas.id/jalan-sehat-dalam-rangka-tasyakuran-keberhasilan-penyatuan-kampus-itb-aas-indonesia-dengan-akademi-kebidanan-giri-satria-husada-wonogiri/"},
  {"q":"Apa bedanya itbaas.id dan itbaas.ac.id?","a":"Keduanya situs resmi/mirror dengan konten hampir sama; pendaftaran tetap di pmb.itbaas.ac.id. Untuk arsip, KB menggabungkan keduanya; jangan anggap salah satunya pihak ketiga.","source":"https://itbaas.id/"},
  {"q":"Ada Tax Center?","a":"Ya. Post menyebut Tax Center ITB AAS meraih peringkat 3 dalam Penghargaan Renjani 2024 Kanwil DJP Jawa Tengah II; juga kerja sama/ MoU dengan DJP Jateng II dan relawan pajak. Detail program tanya Tax Center/kampus.","source":"https://itbaas.ac.id/tax-center-itb-aas-indonesia-raih-peringkat-3-dalam-penghargaan-renjani-2024-kanwil-djp-jateng-2/"},
  {"q":"Ada Galeri Investasi/KSPM?","a":"Ada KSPM GI ITB AAS Indonesia (pasar modal/investasi) dan Galeri Investasi; post menyebut Juara II kategori Pemanfaatan RDIS Terbaik dan hibah komputer dari BEI KP Jateng 2. Instagram KSPM: @kspmgi_itbaas.","source":"https://itbaas.ac.id/galeri-investasi-itb-aas-indonesia-meraih-juara-ii-kategori-pemanfaatan-rdis-terbaik/"},
  {"q":"Ada jurnal ilmiah kampus?","a":"Ada E-Journal ITB AAS dan kanal Kajian Ilmiah Dosen; post menyebut jurnal IJE BAR terakreditasi SINTA. Peringkat/indeks terbaru harus dicek di SINTA/portal jurnal resmi.","source":"https://itbaas.ac.id/jurnal-ijebar-itb-aas-indonesia-terakreditasi-sinta/"},
  {"q":"Ada magang/kunjungan industri?","a":"Ya. Post menyebut kunjungan industri ke PT Victoria Care Indonesia/PT Marifood, BKM Property/Properti Solo Raya, magang/relawan pajak, KKN, pembekalan/sertifikasi; bentuknya per prodi dan per periode.","source":"https://itbaas.id/kunjungan-industri-itb-aas-ke-perumahan-venesia-soba/"},
  {"q":"Apa itu Kampus Merdeka di ITB AAS?","a":"Post website menyebut program Kampus Merdeka: magang industri, pembelajaran berbasis proyek, praktik lapangan, kolaborasi dunia usaha/industri. Skema/konversi SKS per prodi berbeda—tanya kaprodi/PMB.","source":"https://itbaas.id/pilihan-kampus-akreditasi-solo-raya-itb-aas-indonesia/"},
  {"q":"Aturan AI di kampus bagaimana?","a":"Post 2026 mengklaim ada SK Rektor Pedoman Penggunaan AI: mahasiswa boleh memakai AI maksimal 40% untuk tugas akademik; minimal 60% orisinalitas mandiri; S1 Informatika disebut menerapkan AI hingga 40%. Ini klaim post, bukan audit—cek pedoman resmi.","source":"https://itbaas.id/bukan-digantikan-ai-jadi-pengendali-ai-daftar-s1-informatika-unggul-itb-aas-indonesia-sekarang"},
  {"q":"Biaya di brosur boleh dijadikan pegangan?","a":"Tidak. Semua biaya/tanggal/kuota/beasiswa di website dan brosur dapat berubah sesuai kebijakan kampus/pemerintah. Untuk keputusan bayar, minta rincian tertulis dari PMB/keuangan.","source":"https://itbaas.id/"},
  {"q":"Kalau tanya biaya paling murah gimana jawabnya?","a":"Jangan pilih ‘yang paling murah’ mentah-mentah. Sebut: D3 SPP Rp350 ribu/bulan, D4/S1 Rp400 ribu/bulan; DPA naik per gelombang; KIP gratis bila lolos; RPL total ±Rp16–20 juta. Semua perlu dikonfirmasi PMB.","source":"https://itbaas.id/"},
  {"q":"Ada S2 di ITB AAS?","a":"Ada Program Magister Manajemen (S2). Reguler Rp21 juta total (3 semester, termasuk tesis); Dual Degree Rp86 juta; alumni diskon 50% disebut di post. Kuota, status akreditasi S2, dan jadwal terbaru cek PMB/BAN-PT/LAM-PT.","source":"https://itbaas.id/pendaftaran-magister-manajemen-itb-aas-indonesia-2026/"},
  {"q":"Pendaftaran online tetap harus kumpul berkas?","a":"Ya. Syarat pendaftaran menyatakan yang sudah daftar online tetap wajib daftar/kumpul berkas offline di kampus sebagai arsip; ukuran map/warna per prodi berlaku.","source":"https://itbaas.id/syarat-pendaftaran-2/"},
  {"q":"Cara cek legalitas sebelum daftar?","a":"Minta PMB menunjukkan SK pendirian/izin prodi, sertifikat akreditasi, dan bukti PDDIKTI; cek mandiri di pddikti.kemdikbud.go.id, banpt.or.id, atau LAM terkait; telp PMB (0271) 726156 / WA 0889-8337-3916.","source":"https://pmb.itbaas.ac.id/"},
  {"q":"Apa saja yang wajib di-update berkala?","a":"Jalur/tanggal PMB, biaya SPP/DPA, beasiswa, akreditasi, kuota kelas karyawan/online/RPL, dan struktur organisasi. Jadikan `data/admission.json`, `programs.json`, `faq.jsonl` sebagai sumber internal; update bila website resmi berubah.","source":"https://itbaas.ac.id/"},
  {"q":"Prestasi kampus/dosen terbaru apa?","a":"Post 2026 menyebut: S1 Informatika akreditasi Unggul; KSPM juara II RDIS; Tax Center Renjani peringkat 3; dosen PhD University of Dundee; S2 MM dibuka; kerja sama IC-RMUTK Thailand. Semua klaim post—cek sertifikat/pengumuman resmi.","source":"https://itbaas.ac.id/category/prestasi/"},
  {"q":"Apakah biaya dijamin tidak naik?","a":"Tidak. Halaman biaya mencantumkan berlaku untuk tahun akademik berjalan dan dapat berubah sewaktu-waktu. Jangan janjikan nominal ke user; selalu tandai ‘sesuai info terbaru PMB’.","source":"https://itbaas.id/"},
]
with open(ROOT/'data/faq.jsonl','a',encoding='utf-8') as f:
    for r in rows: f.write(json.dumps(r, ensure_ascii=False)+'\n')
print('appended', len(rows))
